/**
 * Copy the README screenshots into the site's public directory.
 *
 * They are not committed twice on purpose: `docs/images/*.png` is generated by
 * `bun run docs:shots` from the real CLI against `examples/perch`, and a second
 * committed copy would drift from it the first time the output changed. This
 * runs before dev and before build, so the site always ships whatever the last
 * shoot produced.
 */
import { cp, mkdir, readdir } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const FROM = path.resolve(HERE, "../../docs/images");
const TO = path.resolve(HERE, "../public/images");

const entries = await readdir(FROM).catch(() => {
  throw new Error(
    `no screenshots at ${FROM} — run \`bun run docs:shots\` in the repo root first`
  );
});

const shots = entries.filter((name) => name.endsWith(".png"));
if (shots.length === 0) throw new Error(`no .png files in ${FROM}`);

await mkdir(TO, { recursive: true });
for (const name of shots) {
  await cp(path.join(FROM, name), path.join(TO, name));
}

console.log(`assets: ${shots.length} screenshot(s) → site/public/images/`);
